let allProducts=[],currentCategory="all",searchQuery="";function setupNavigation(){const e=document.getElementById("mobileMenuBtn"),a=document.getElementById("navMenu");if(e&&a){e.addEventListener("click",()=>{a.classList.toggle("open")}),document.querySelectorAll(".nav-item").forEach(e=>{e.addEventListener("click",()=>{a.classList.remove("open")})});const t=document.getElementById("mobileCategoriesList");t&&window.CATEGORIES&&(t.innerHTML="",Object.values(window.CATEGORIES).forEach(e=>{const a=document.createElement("a");a.href=`catalog.html?category=${e.id}`,a.innerHTML=`<i class="fas ${e.icon||"fa-tag"}"></i> ${e.name}`,t.appendChild(a)}))}window.addEventListener("scroll",()=>{const e=document.getElementById("header");e&&(window.scrollY>50?e.style.boxShadow="0 6px 25px rgba(0, 0, 0, 0.08)":e.style.boxShadow="0 4px 20px rgba(0, 0, 0, 0.03)")})}async function loadAndRenderProducts(){const e=await window.YellowRoseDB.getCategories();window.CATEGORIES={},e.forEach(e=>window.CATEGORIES[e.id]=e);const a=document.getElementById("categoryTabs");a&&(a.innerHTML='\n      <button class="cat-btn active" data-category="all">\n        <div class="cat-img-wrapper">\n          <i class="fas fa-th cat-fallback-icon"></i>\n        </div>\n        <span>الكل</span>\n      </button>\n    ',e.forEach(e=>{const t=e.coverUrl?`<img src="${e.coverUrl}" alt="${e.name}" class="cat-img" loading="lazy">`:`<i class="fas ${e.icon||"fa-tag"} cat-fallback-icon"></i>`;a.innerHTML+=`\n        <button class="cat-btn" data-category="${e.id}">\n          <div class="cat-img-wrapper">\n            ${t}\n          </div>\n          <span>${e.name}</span>\n        </button>\n      `}),document.querySelectorAll(".cat-btn").forEach(e=>{e.addEventListener("click",()=>{document.querySelectorAll(".cat-btn").forEach(e=>e.classList.remove("active")),e.classList.add("active"),currentCategory=e.getAttribute("data-category"),filterProducts()})}));const t=document.getElementById("galleryGrid");if(t){t.innerHTML='<div class="loading-spinner"><i class="fas fa-circle-notch fa-spin"></i> جاري تحميل المنتجات...</div>';try{allProducts=await window.YellowRoseDB.getProducts(),updateCategoryCounts(),renderGallery()}catch(e){t.innerHTML='\n      <div style="grid-column: 1 / -1; text-align: center; padding: 40px;">\n        <p style="color: #c0392b;">حدث خطأ أثناء تحميل المنتجات، يرجى إعادة المحاولة.</p>\n      </div>\n    '}}}function renderGallery(){const e=document.getElementById("galleryGrid"),a=document.getElementById("noItemsMessage");if(!e)return;e.innerHTML="";const t=Object.values(window.CATEGORIES);let n=0;t.forEach(a=>{if("all"!==currentCategory&&a.id!==currentCategory)return;if(searchQuery&&!a.name.toLowerCase().includes(searchQuery.toLowerCase()))return;const t=allProducts.filter(e=>e.categoryId===a.id);let c=0,r="assets/logo.png",s=!1;if(!(t.length>0))return;t.forEach(e=>{e.images&&e.images.length>0&&(c+=e.images.length),e.featured&&(s=!0)});for(let e=t.length-1;e>=0;e--){const a=t[e];if(a.coverUrl){r=a.coverUrl;break}if(a.images&&a.images.length>0){r=a.images[0].thumbnailUrl||a.images[0].url;break}}n++;const l=document.createElement("div");l.className="album-card category-card",l.setAttribute("data-id",a.id),l.innerHTML=`\n      <div class="card-img-wrapper">\n        <a href="catalog.html?category=${a.id}" class="card-img-link" title="استعراض قسم ${escapeHtml(a.name)}">\n          <img src="${escapeHtml(r)}" alt="${escapeHtml(a.name)}" class="card-img" loading="lazy" onerror="this.src='assets/logo.png';">\n        </a>\n        <span class="card-category-badge" style="top: 15px; left: auto; right: 15px; background: rgba(0,0,0,0.6); backdrop-filter: blur(5px);">\n          <i class="fas ${a.icon||"fa-tag"}"></i> ${escapeHtml(a.name)}\n        </span>\n        <span class="card-photo-count">\n          <i class="fas fa-camera"></i> ${c} ${c>10?"منتج":"منتجات"}\n        </span>\n        ${s?'<span class="card-featured-badge"><i class="fas fa-star"></i> قسم مميز</span>':""}\n      </div>\n\n      <div class="card-body">\n        <h3 class="card-title" style="margin-bottom: 5px;">\n          <a href="catalog.html?category=${a.id}">${escapeHtml(a.name)}</a>\n        </h3>\n        <p class="card-desc">استعرض جميع صور وتنسيقات قسم ${escapeHtml(a.name)} بشكل مباشر.</p>\n        \n        <div class="card-album-actions" style="margin-top: 15px;">\n          <a href="catalog.html?category=${a.id}" class="btn-card-album" style="width: 100%; justify-content: center;">\n            <i class="fas fa-images"></i> عرض جميع المنتجات للقسم\n          </a>\n        </div>\n      </div>\n    `,e.appendChild(l)}),0===n?a&&a.classList.remove("hidden"):a&&a.classList.add("hidden")}function updateCategoryCounts(){}function setupFilterAndSearch(){document.querySelectorAll(".cat-btn").forEach(e=>{e.addEventListener("click",()=>{document.querySelectorAll(".cat-btn").forEach(e=>e.classList.remove("active")),e.classList.add("active"),currentCategory=e.getAttribute("data-category"),renderGallery()})});const e=document.getElementById("gallerySearchInput");e&&e.addEventListener("input",e=>{searchQuery=e.target.value.trim(),renderGallery()})}function escapeHtml(e){return e?String(e).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;"):""}document.addEventListener("DOMContentLoaded",async()=>{await window.YellowRoseDB.syncSiteSettingsToDom(),setupNavigation(),await loadAndRenderProducts(),setupFilterAndSearch()});